issues.suggestion:
The validation function should return the trimmed text when valid to ensure the same trimmed value is used. Example:
```javascript
export function validateTodoText(text) {
  if (typeof text !== 'string') {
    return { valid: false, error: 'text must be a string' };
  }
  const trimmed = text.trim();
  if (trimmed.length === 0) {
    return { valid: false, error: 'text must not be empty' };
  }
  if (trimmed.length > MAX_TODO_TEXT_LENGTH) {
    return { valid: false, error: `text must be at most ${MAX_TODO_TEXT_LENGTH} characters` };
  }
  return { valid: true, sanitized: trimmed };
}

app.post('/todos', (req, res) => {
  const { text } = req.body;
  const validation = validateTodoText(text);
  if (!validation.valid) {
    return res.status(400).json({ error: validation.error });
  }
  res.status(201).json(addTodo(validation.sanitized));
});
```

